function validate([pizzas]) {
  const n = pizzas.length;
  if (n < 4 || n > 200000) return 'pizzas needs 4 to 2 * 10^5 weights.';
  if (n % 4 !== 0) return 'The number of pizzas must be a multiple of 4.';
  if (pizzas.some(w => w < 1 || w > 100000)) return 'Each weight is between 1 and 10^5.';
  return null;
}

