function maxWeight(pizzas) {
  pizzas.sort((a, b) => a - b);
  const days = pizzas.length / 4;
  const oddDays = Math.ceil(days / 2);
  const evenDays = days - oddDays;
  let right = pizzas.length - 1;
  let total = 0;
  for (let day = 0; day < oddDays; day++) {
    total += pizzas[right];
    right--;
  }
  for (let day = 0; day < evenDays; day++) {
    right--;
    total += pizzas[right];
    right--;
  }
  return total;
}

