function maxWeight(pizzas) {
  // Try every choice of four uneaten pizzas for each day in turn, remembering the best result for each set already eaten.
  const n = pizzas.length;
  const memo = new Map();
  const best = (eaten, day) => {
    if (day * 4 === n) return 0;
    if (memo.has(eaten)) return memo.get(eaten);
    const free = [];
    for (let i = 0; i < n; i++) if (!(eaten & (1 << i))) free.push(i);
    let result = -Infinity;
    for (let a = 0; a < free.length; a++)
      for (let b = a + 1; b < free.length; b++)
        for (let c = b + 1; c < free.length; c++)
          for (let d = c + 1; d < free.length; d++) {
            const group = [pizzas[free[a]], pizzas[free[b]], pizzas[free[c]], pizzas[free[d]]].sort((x, y) => x - y);
            const gain = day % 2 === 0 ? group[3] : group[2];
            const after = eaten | (1 << free[a]) | (1 << free[b]) | (1 << free[c]) | (1 << free[d]);
            result = Math.max(result, gain + best(after, day + 1));
          }
    memo.set(eaten, result);
    return result;
  };
  return best(0, 0);
}

