function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? 4 * pick(490, 500) : 4 * pick(1, 3);
  // Small inputs mostly use a few distinct weights so that ties are common; some use the full range.
  const top = large || rand() < 0.2 ? 100000 : pick(1, 12);
  return [Array.from({ length: n }, () => pick(1, top))];
}
